import glob, re
from collections import Counter, defaultdict

def strip_comments(s):
    out=[]; i,n=0,len(s); ins=False
    while i<n:
        c=s[i]
        if ins:
            out.append(c)
            if c=='"': ins=False
            i+=1
        elif c=='"':
            ins=True; out.append(c); i+=1
        elif c=='#':
            while i<n and s[i] not in '\r\n': out.append(' '); i+=1
        else:
            out.append(c); i+=1
    return ''.join(out)

def match_brace(s,p):
    d=0
    for i in range(p,len(s)):
        if s[i]=='{': d+=1
        elif s[i]=='}':
            d-=1
            if d==0: return i+1
    return None

files=sorted(glob.glob('characters/*.txt'))
blocks={}; dups=[]
for f in files:
